'use strict';
let store, csrf, serverToday, cloudMode=false, page='home', scope='', contentView='board', financeView='ledger', resourceType='', monthOffset=0;
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => serverToday || new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'});
const money = n => '৳'+new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format((n||0)/100);
const shortDate = s => s ? new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}) : 'Not set';
const fullDate = s => new Date(s+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'});
const business = id => store.businesses.find(b=>b.id===id);
const client = id => store.clients.find(c=>c.id===id);
const bname = id => business(id)?.name || 'Shared workspace';
const cname = id => client(id)?.name || '—';
const initials = name => name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();
const color = id => /^#[0-9a-f]{6}$/i.test(business(id)?.color||'') ? business(id).color : '#628779';
const all = entity => store[entity].filter(r=>!scope || entity==='reviews' || r.business_id===scope || (['resources','recipes'].includes(entity)&&!r.business_id) || (entity==='businesses'&&r.id===scope));
const found = (entity,id) => store[entity].find(r=>r.id===id);
const due = s => s && s<today();
const inMonth = date => date?.slice(0,7)===today().slice(0,7);
const total = (items,key='amount') => items.reduce((sum,x)=>sum+(x[key]||0),0);
const balance = inv => inv.amount-inv.paid;
const openInvoices = () => all('invoices').filter(i=>balance(i)>0);
const reviewItems = () => all('content').filter(c=>c.status==='In review');
const ledger = () => all('transactions').filter(t=>inMonth(t.date));
const income = items => total(items.filter(t=>t.kind==='Income'));
const expenses = items => total(items.filter(t=>t.kind==='Expense'));
const iconPaths={
 home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7', today:'M8 2v4m8-4v4M3 9h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M7 13h3m4 0h3m-10 4h3', businesses:'M3 21V5h10v16M13 10h8v11M6 9h4m-4 4h4m-4 4h4m6-3h2m-2 4h2M2 21h20', clients:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8m5 9v-3a4 4 0 0 0-3-4', projects:'M3 5h7l2 2h9v13H3z', tasks:'M9 5h12M9 12h12M9 19h12M2 4l2 2 3-4M2 11l2 2 3-4M2 18l2 2 3-4', marketing:'M3 10v5h4l12 5V5L7 10H3 M7 15l2 6h4l-2-4 M22 10v5', content:'M5 3h10l4 4v14H5z M14 3v5h5M8 12h8m-8 4h8', sales:'M3 21V11h4v10M10 21V7h4v14M17 21V3h4v18', finance:'M3 6h18v14H3zM3 10h18M15 15h3M6 15h3', resources:'M12 2l9 5v10l-9 5-9-5V7z M3 7l9 5 9-5m-9 5v10', automations:'M13 2L4 14h7l-1 8 10-13h-7z', reports:'M4 3h16v18H4zM8 15h2v3H8m6-7h2v7h-2M8 7h8', ai:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 4-2 3v3l-4 3-3-1-3 1-4-3v-3l-2-3 2-4 3-1z', search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6', plus:'M12 5v14M5 12h14', down:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5', chevron:'M9 5l7 7-7 7', close:'M6 6l12 12M6 18 18 6', edit:'M14 4l6 6M4 20l4-1L21 6l-4-4L4 15z', check:'M4 12l5 5L20 6', clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 4v6l4 2', info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 4v2m0 3v7', menu:'M3 6h18M3 12h18M3 18h18', back:'M15 5l-7 7 7 7', link:'M10 14l4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 0 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0', empty:'M4 7h16v14H4zM7 3h10v4M9 12h6', alert:'M12 3l10 18H2zM12 9v5m0 3v1', user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-8 18v-3a6 6 0 0 1 6-4h4a6 6 0 0 1 6 4v3', copy:'M8 7h13v14H8zM16 7V3H3v13h5', trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7'
};
const icon = name => `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[name]||iconPaths.content}"/></svg>`;
const badge = status => `<span class="badge ${['Approved','Published','Active','Done','Won','Paid'].includes(status)?'good':['In review','Onboarding','Qualified','Review','Proposal'].includes(status)?'purple':['Overdue','Blocked','Rejected','Lost'].includes(status)?'bad':['Changes requested','Scheduled','In progress','Partial'].includes(status)?'warn':'neutral'}">${esc(status)}</span>`;
const brandIcon = id => `<span class="brand-icon" style="background:${color(id)}">${esc(initials(bname(id)))}</span>`;
const btn = (label,action,extra='',style='secondary') => `<button class="btn ${style}" data-action="${action}" ${extra}>${esc(label)}</button>`;
const navbtn = (label,target,style='secondary') => btn(label,'navigate',`data-page="${target}"`,style);
const editbtn = (entity,id,label='Edit') => btn(label,'edit',`data-entity="${entity}" data-id="${esc(id)}"`,'secondary compact');
const empty = (title,text,action='') => `<div class="empty">${icon('empty')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
const addbtn = (entity,label) => btn(label,'edit',`data-entity="${entity}"`,'primary');
const NAV=[['home','Command Center'],['today','Today'],['businesses','Businesses'],['clients','Clients'],['projects','Projects'],['tasks','Tasks'],['marketing','Marketing'],['content','Content'],['sales','Sales & CRM'],['finance','Finance'],['resources','Resources'],['automations','Automations'],['reports','Reports'],['ai','GROW AI'],['settings','Settings']];
const entityPage={businesses:'businesses',clients:'clients',projects:'projects',tasks:'tasks',plans:'marketing',content:'content',leads:'sales',transactions:'finance',invoices:'finance',resources:'resources',recipes:'automations',reviews:'reports'};

async function api(path,method='GET',data){
  const res=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Grow-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});
  const result=await res.json(); if(res.status===401){location.replace('/login');throw new Error('Please sign in again.');} if(!res.ok) throw new Error(result.error||'Could not save. Try again.'); return result;
}
async function refresh(){const state=await api('state');store=state.data;csrf=state.csrf;serverToday=state.today;cloudMode=state.deployment==='cloud';}
let toastTimer;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function go(target){page=NAV.some(n=>n[0]===target)?target:'home';location.hash=page;render();window.scrollTo({top:0});}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1>${subtitle?`<p class="route-intro">${esc(subtitle)}</p>`:''}</div><div class="page-actions">${actions}</div></div>`;}
function stat(label,value,detail,ic='content',featured=false){return `<article class="stat ${featured?'featured':''}"><div class="stat-label">${esc(label)}${icon(ic)}</div><div class="stat-value">${esc(value)}</div><div class="stat-detail">${detail}</div></article>`;}
function card(title,body,action='',cls=''){return `<section class="card ${cls}"><div class="card-head"><h2>${esc(title)}</h2>${action}</div>${body}</section>`;}
const sampleCount=()=>Object.keys(entityPage).reduce((n,key)=>n+store[key].filter(r=>r.demo).length,0);

function render(){
 const name=NAV.find(n=>n[0]===page)?.[1]||'Command Center';document.title='GROW · '+name;
 const sections={home:homePage,today:todayPage,businesses:businessesPage,clients:clientsPage,projects:projectsPage,tasks:tasksPage,marketing:marketingPage,content:contentPage,sales:salesPage,finance:financePage,resources:resourcesPage,automations:automationsPage,reports:reportsPage,ai:aiPage,settings:settingsPage};
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">G</div><div><strong>GROW</strong><small>YOUR BUSINESS OS</small></div></div><nav aria-label="Main navigation">${NAV.map(([id,label],i)=>`${i===0?'<div class="nav-label">Workspace</div>':i===6?'<div class="nav-label">Growth & operations</div>':i===11?'<div class="nav-label">Intelligence</div>':''}<a href="#${id}" data-action="navigate" data-page="${id}" class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='content'&&reviewItems().length?`<span class="count">${reviewItems().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-label"><i></i>${cloudMode?'Cloud workspace':'Local workspace'}</div><p>${cloudMode?'Saved securely online':'Saved on this computer'}</p></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span><span>/</span><span>${name}</span></div><div class="topbar-right"><button class="search-button" data-action="search">${icon('search')}<span>Search workspace</span><kbd>Ctrl K</kbd></button><select id="scope" aria-label="Business workspace"><option value="">All businesses</option>${store.businesses.map(b=>`<option value="${esc(b.id)}" ${scope===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>${cloudMode?btn('Sign out','logout','','secondary compact'):''}<div class="avatar" title="${esc(store.settings.owner)}">${esc(initials(store.settings.owner||'Jubayer'))}</div></div></header><div class="page">${sampleCount()?`<div class="sample-banner">${icon('info')}<span>Sample records are included. Financial amounts, clients and activity are examples.</span><button data-action="navigate" data-page="settings">Manage samples</button></div>`:''}${sections[page]()}<footer class="summary-footer"><span>GROW / Growth · Revenue · Operations · Workflows</span><span>${cloudMode?'Cloud':'Local'} edition 1.0 · Asia/Dhaka · BDT</span></footer></div></main></div>`;
}

function weekTheme(){const day=new Date(today()+'T12:00:00').getDay();return ['CEO planning + I am Jubayer','Vidzones','QFS','CNMOTOS + AlabamaFootball','Biggan PiC / GhuraghuriBD','Day off','Day off'][day];}
function focusBody(){const day=new Date(today()+'T12:00:00').getDay();if(day>=5)return `<div class="card-body"><p>Your planned day off.</p><p class="muted small">Friday and Saturday are protected. Review exceptions when needed.</p></div>`;
return `<div class="card-body">${[['10:30–12:30','Artbit deep work','Strategy, proposals and important creative work'],['12:45–14:15','Artbit client operations','Communication, team review and approvals'],['15:00–17:00',weekTheme(),'One secondary business theme'],['17:15–18:00',day===4?'Weekly review + batch approval':'Decision & approval window','Review exceptions; finish with a clear next step']].map(([time,title,description],i)=>`<div class="focus-row"><span class="focus-time">${time}</span><i class="focus-bar ${i?'dim':''}"></i><div><strong>${title}</strong><p>${description}</p></div></div>`).join('')}</div>`;}
function attentionItems(){return [
...openInvoices().filter(i=>due(i.due)).map(i=>({title:i.title,text:`${money(balance(i))} overdue · ${bname(i.business_id)}`,page:'finance',entity:'invoices',id:i.id,kind:'finance'})),
...all('projects').filter(p=>p.status!=='Done'&&due(p.due)).map(p=>({title:p.title,text:`Project overdue · ${bname(p.business_id)}`,page:'projects',entity:'projects',id:p.id,kind:'projects'})),
...all('leads').filter(l=>!['Won','Lost'].includes(l.stage)&&l.next_date&&l.next_date<=today()).map(l=>({title:l.name,text:`Follow-up due · ${bname(l.business_id)}`,page:'sales',entity:'leads',id:l.id,kind:'sales'})),
...all('resources').filter(r=>r.renewal&&r.renewal<=addDays(today(),7)).map(r=>({title:r.name,text:`Renewal ${shortDate(r.renewal)} · ${money(r.cost)}`,page:'resources',entity:'resources',id:r.id,kind:'resources'}))
];}
function addDays(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);}
function attentionRows(limit=4){const list=attentionItems().slice(0,limit);return list.length?`<div class="row-list">${list.map(a=>`<div class="list-row"><div class="brand-icon" style="background:#f4efe5;color:#8c7544">${icon(a.kind)}</div><div class="grow"><strong>${esc(a.title)}</strong><p>${esc(a.text)}</p></div>${editbtn(a.entity,a.id,'Review')}</div>`).join('')}</div>`:empty('A clear runway','No overdue invoices, follow-ups or projects in this workspace.');}
function approvalRows(limit=3){const items=reviewItems().slice(0,limit);return items.length?`<div class="row-list">${items.map(c=>`<div class="list-row">${brandIcon(c.business_id)}<div class="grow"><strong>${esc(c.title)}</strong><p>${esc(bname(c.business_id))} · ${esc(c.channel)}</p></div>${btn('Review','review-content',`data-id="${esc(c.id)}"`,'secondary compact')}</div>`).join('')}</div>`:empty('All reviews are clear','New content appears here after you submit it for review.',addbtn('content','New content'));}
function businessHealth(b){const records=store.content.filter(c=>c.business_id===b.id);const overdue=store.projects.some(p=>p.business_id===b.id&&p.status!=='Done'&&due(p.due))||store.invoices.some(i=>i.business_id===b.id&&balance(i)>0&&due(i.due));return overdue?'Needs attention':records.some(c=>c.status==='In review')?'Review pending':'On track';}
function portfolio(){const list=all('businesses');return `<div class="table-wrap"><table class="portfolio-table"><thead><tr><th>Business</th><th>Attention</th><th>Content ready</th><th>Net cash · month</th><th></th></tr></thead><tbody>${list.map(b=>{const ts=store.transactions.filter(t=>t.business_id===b.id&&inMonth(t.date));const health=businessHealth(b);return `<tr><td><div class="business-cell">${brandIcon(b.id)}<div><strong>${esc(b.name)}</strong><span class="muted">${esc(b.kind)}</span></div></div></td><td>${badge(health==='Needs attention'?'Overdue':health==='Review pending'?'In review':health)}</td><td>${store.content.filter(c=>c.business_id===b.id&&['Approved','Scheduled'].includes(c.status)).length} assets</td><td>${money(income(ts)-expenses(ts))}</td><td><button class="table-action" aria-label="Open ${esc(b.name)}" data-action="workspace" data-id="${esc(b.id)}">${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table></div><div class="portfolio-foot">Attention is based on recorded activity. Net cash uses recorded income and expenses.</div>`;}
function homePage(){const ts=ledger(), inc=income(ts),exp=expenses(ts);return heading('Your day, with direction.',`${fullDate(today())} · ${scope?bname(scope):'One workspace. Every business.'}`,`<a class="btn secondary" href="/api/backup">${icon('down')} Backup</a>${addbtn('content','New content')}`)+`<div class="stats">${stat('Needs your review',reviewItems().length,'Content awaiting approval','check',true)}${stat('Ready to publish',all('content').filter(c=>['Approved','Scheduled'].includes(c.status)).length,'Approved and planned assets','content')}${stat('Recorded income',money(inc),'This month · BDT','finance')}${stat('Outstanding',money(total(openInvoices().map(i=>({amount:balance(i)})))),'Unpaid invoice balances','clock')}</div><div class="grid"><div class="stack">${card('Business portfolio',portfolio(),navbtn('View businesses','businesses','secondary compact'))}${card('Approval inbox',approvalRows(),btn('View all','content-approvals','','secondary compact'))}</div><div class="stack">${card('Today’s focus',focusBody(),`<span class="focus-day">${new Date(today()+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long'})}</span>`,'focus-card')}${card('Needs attention',attentionRows(),`<span class="badge warn">${attentionItems().length} items</span>`)}${card('Monthly cash snapshot',`<div class="card-body"><dl class="key-value"><div><dt>Income / expenses</dt><dd>${money(inc)} / ${money(exp)}</dd></div><div><dt>Net recorded cash flow</dt><dd><strong>${money(inc-exp)}</strong></dd></div></dl><p class="notice">Opening balances, taxes and accrual accounting are outside this local ledger.</p></div>`,navbtn('Open finance','finance','secondary compact'))}</div></div>`;}
function todayPage(){return heading('Today','Artbit gets daily attention. Other businesses get one focused block.',navbtn('Review content','content'))+`<div class="grid"><div class="stack">${card('Protected work blocks',focusBody(),'','focus-card')}${card('Priority decisions',attentionRows(12))}</div><div class="stack">${card('Content review',approvalRows(8))}${card('Task manager snapshot',taskRows(all('tasks').filter(t=>t.status!=='Done').slice(0,5)),navbtn('Open tasks','tasks','secondary compact'))}</div></div><section class="section-gap"><div class="card-head" style="padding-left:0;border:0"><h2>Your five-day rhythm</h2><span class="muted small">Friday & Saturday off</span></div>${schedule()}</section>`;}
function schedule(){return `<div class="schedule-grid">${['Sunday','Monday','Tuesday','Wednesday','Thursday'].map((d,i)=>`<div class="schedule-day ${new Date(today()+'T12:00:00').getDay()===i?'current':''}"><h3>${d}</h3><span class="badge good">Artbit Studio</span><p>15:00–17:00</p><p>${['CEO + I am Jubayer','Vidzones','QFS','CNMOTOS + AlabamaFootball','Biggan PiC / GhuraghuriBD'][i]}</p>${i===0||i===4?'<p><strong>Batch content review</strong></p>':''}</div>`).join('')}</div>`;}
function businessesPage(){
 if(scope){const b=business(scope);if(!b){scope='';return businessesPage();}const list=all('projects');return heading(b.name,b.focus,`${editbtn('businesses',b.id,'Edit business')}${btn('All workspaces','clear-scope')}`)+`<div class="stats">${stat('Projects',list.filter(p=>p.status!=='Done').length,'Active delivery','projects')}${stat('Content',all('content').length,'Across channels','content',true)}${stat('Pipeline',money(total(all('leads').filter(l=>!['Won','Lost'].includes(l.stage)),'value')),'Open estimated deal value','sales')}${stat('Outstanding',money(total(openInvoices().map(i=>({amount:balance(i)})))),'Invoice balance','finance')}</div><div class="two-column">${card('Marketing profile',`<div class="card-body"><dl class="key-value">${[['Positioning / focus',b.focus],['Target audience',b.target],['Channels',b.channels],['Content pillars',b.pillars],['Current goal',b.goal]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Not set')}</dd></div>`).join('')}</dl></div>`)}${card('Workspace actions',`<div class="row-list">${[['projects','Projects and delivery'],['content','Content and approvals'],['finance','Income, expenses and invoices'],['resources','Assets, people and subscriptions'],['sales','Leads and relationships']].map(([p,label])=>`<div class="list-row"><div class="grow"><strong>${label}</strong></div>${navbtn('Open',p,'secondary compact')}</div>`).join('')}</div>`)}</div>`;}
 return heading('Business workspaces','Independent operations, connected in one command center.',addbtn('businesses','Add business'))+`<div class="three-column">${store.businesses.map(b=>`<article class="card business-card"><div class="business-card-top">${brandIcon(b.id)}<div><h3>${esc(b.name)}</h3><span class="muted small">${esc(b.kind)}</span></div></div><p>${esc(b.focus)}</p><p>${esc(b.goal)}</p><div class="business-numbers"><div><strong>${store.content.filter(c=>c.business_id===b.id).length}</strong>Content items</div><div><strong>${store.projects.filter(p=>p.business_id===b.id&&p.status!=='Done').length}</strong>Active projects</div></div>${btn('Open workspace','workspace',`data-id="${esc(b.id)}"`)}</article>`).join('')}</div>`;
}
function table(headers,body){return `<div class="card table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;}
function clientsPage(){const items=all('clients');return heading('Client workspaces','Agency clients stay under Artbit; each client has its own delivery and billing records.',addbtn('clients','Add client'))+(items.length?`<div class="three-column">${items.map(c=>{const inv=store.invoices.filter(i=>i.client_id===c.id);return `<article class="card business-card"><div class="business-card-top"><div class="brand-icon" style="background:#769489">${esc(initials(c.name))}</div><div><h3>${esc(c.name)}</h3><span class="muted small">${esc(bname(c.business_id))}</span></div></div><div>${badge(c.status)}</div><p>${esc(c.contact||'Add a contact')} ${c.email?`· ${esc(c.email)}`:''}</p><div class="business-numbers"><div><strong>${money(c.fee)}</strong>Monthly fee</div><div><strong>${money(total(inv.map(i=>({amount:balance(i)}))))}</strong>Outstanding</div></div><p>${store.content.filter(x=>x.client_id===c.id&&x.status==='In review').length} approvals · ${store.projects.filter(x=>x.client_id===c.id&&x.status!=='Done').length} active projects</p><div class="page-actions">${editbtn('clients',c.id,'Client details')}${btn('Delivery','client-delivery',`data-id="${esc(c.id)}"`,'secondary compact')}</div></article>`;}).join('')}</div>`:empty('Add your first client','Link the client to Artbit Studio and start connecting delivery, content and invoices.',addbtn('clients','Add client')));}
function projectsPage(){const items=all('projects');return heading('Projects','Delivery across your businesses and agency clients.',addbtn('projects','New project'))+(items.length?table(['Project','Business / client','Due','Status',''],items.map(p=>`<tr><td><strong>${esc(p.title)}</strong><span class="muted">${esc(p.notes).slice(0,85)}</span></td><td>${esc(bname(p.business_id))}<span class="muted">${esc(cname(p.client_id))}</span></td><td>${shortDate(p.due)}${due(p.due)&&p.status!=='Done'?` ${badge('Overdue')}`:''}</td><td>${badge(p.status)}</td><td>${editbtn('projects',p.id)}</td></tr>`).join('')):empty('No projects yet','Add a project and link its business, client and delivery date.',addbtn('projects','New project')));}
function taskRows(items){return items.length?`<div class="row-list">${items.map(t=>`<div class="list-row"><div class="grow"><strong>${esc(t.title)}</strong><p>${esc(bname(t.business_id))} · ${shortDate(t.due)} · ${esc(t.priority)}</p></div>${badge(t.status)}${safeLink(t.url||store.settings.task_manager_url,'Open','btn secondary compact')}</div>`).join('')}</div>`:empty('Connect your task engine','Import task statuses from your existing tool. GROW reads the snapshot; your tool remains the place to manage tasks.');}
function safeLink(url,label,cls='link-btn'){if(!url)return '';try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '';}catch{return '';}return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;}
function tasksPage(){const items=all('tasks');return heading('Your task engine','A read-only overview from the tool you already built.',`${btn('Import status JSON','import-tasks')}${store.settings.task_manager_url?safeLink(store.settings.task_manager_url,'Open task manager','btn primary'):navbtn('Set task manager URL','settings','primary')}`)+`<div class="info">${icon('info')}The task connection is not live. Importing a new snapshot updates matching external IDs; it does not create or change tasks in your tool.</div>${card('Imported task statuses',taskRows(items),`<span class="badge neutral">${items.length} tasks</span>`)}<div class="section-gap">${card('Import format',`<div class="card-body"><p class="muted small">Use a JSON object with a tasks array. Required: title, business_id, status and external_id. Optional: due, priority, client_id and url.</p><pre class="import-code">${esc(JSON.stringify({tasks:[{external_id:'your-task-123',title:'Review campaign',business_id:'artbit',status:'Open',priority:'High',due:today(),url:store.settings.task_manager_url||'http://localhost:3000'}]},null,2))}</pre>${btn('Download example','task-example')}</div>`)}</div>`;}
function marketingPage(){const plans=all('plans');return heading('Marketing planner','Positioning, channels and a measurable plan for every business.',addbtn('plans','New marketing plan'))+`<div class="three-column">${all('businesses').map(b=>`<article class="card business-card"><div class="business-card-top">${brandIcon(b.id)}<h3>${esc(b.name)}</h3></div><dl class="key-value"><div><dt>Primary channels</dt><dd>${esc(b.channels)}</dd></div><div><dt>Content pillars</dt><dd>${esc(b.pillars)}</dd></div><div><dt>Goal</dt><dd>${esc(b.goal)}</dd></div></dl>${editbtn('businesses',b.id,'Edit profile')}</article>`).join('')}</div><div class="section-gap">${card('Campaign & marketing plans',plans.length?`<div class="row-list">${plans.map(p=>`<div class="list-row">${brandIcon(p.business_id)}<div class="grow"><strong>${esc(p.title)}</strong><p>${esc(p.objective)}</p><p>${esc(p.cadence)} · KPI: ${esc(p.kpi)}</p></div>${editbtn('plans',p.id,'Open plan')}</div>`).join('')}</div>`:empty('Turn positioning into a plan','Set an objective, audience, content cadence and success metric.',addbtn('plans','New plan')))}</div>`;}
function contentPage(){return heading('Content studio','One content engine. Review in batches, then hand off approved assets.',addbtn('content','New content'))+`<div class="toolbar"><div class="tabs" role="tablist" aria-label="Content views">${[['board','Pipeline'],['approvals','Approvals'],['calendar','Calendar'],['list','All content']].map(([v,l])=>`<button role="tab" aria-selected="${contentView===v}" class="${contentView===v?'selected':''}" data-action="content-view" data-view="${v}">${l}${v==='approvals'?` (${reviewItems().length})`:''}</button>`).join('')}</div><span class="muted small">${all('content').length} assets · Publisher not connected</span></div>${contentView==='board'?contentBoard():contentView==='approvals'?contentApprovals():contentView==='calendar'?contentCalendar():contentList()}`;}
function contentBoard(){const groups=[['Ideas & drafts',['Idea','Draft','Changes requested']],['In review',['In review']],['Approved & planned',['Approved','Scheduled']],['Published & rejected',['Published','Rejected']]];return `<div class="board">${groups.map(([name,statuses])=>{const items=all('content').filter(c=>statuses.includes(c.status));return `<section class="board-column"><div class="board-title"><span>${name}</span><span class="badge neutral">${items.length}</span></div>${items.map(c=>`<article class="board-item">${badge(c.status)}<h3>${esc(c.title)}</h3><p>${esc(bname(c.business_id))}${c.client_id?' / '+esc(cname(c.client_id)):''}</p><div class="metadata"><span>${esc(c.channel)} · ${esc(c.format)}</span></div><div class="metadata"><span>${shortDate(c.date)}</span>${icon('clock')}</div><div class="actions">${editbtn('content',c.id,'Open')}${['Draft','Changes requested'].includes(c.status)?statusbtn(c,'In review','Submit'):c.status==='In review'?btn('Review','review-content',`data-id="${esc(c.id)}"`,'primary compact'):c.status==='Approved'?statusbtn(c,'Scheduled','Plan publish'):c.status==='Scheduled'?statusbtn(c,'Published','Confirm published'):c.status==='Idea'?statusbtn(c,'Draft','Start draft'):''}</div></article>`).join('')}${!items.length?'<p class="muted small">No items in this stage.</p>':''}</section>`;}).join('')}</div>`;}
function statusbtn(c,status,label,style='secondary compact'){return btn(label,'content-status',`data-id="${esc(c.id)}" data-status="${status}"`,style);}
function contentApprovals(){const items=reviewItems();return items.length?`<div class="two-column">${items.map(c=>`<article class="card approval-card"><div class="business-card-top">${brandIcon(c.business_id)}<div><strong>${esc(bname(c.business_id))}</strong><p class="muted small">${esc(cname(c.client_id))} · ${esc(c.channel)} · ${shortDate(c.date)}</p></div></div><h3>${esc(c.title)}</h3><span class="badge purple">${esc(c.format)}</span><div class="copy">${esc(c.copy||'No copy added. Open the draft before approving.')}</div>${c.notes?`<p class="notice">${esc(c.notes)}</p>`:''}<div class="actions">${statusbtn(c,'Approved','Approve','primary')}${statusbtn(c,'Changes requested','Request changes')}${statusbtn(c,'Rejected','Reject')}${editbtn('content',c.id,'Edit draft')}</div></article>`).join('')}</div>`:empty('Approval queue is clear','Submit drafts for review to prepare your next batch.',btn('View pipeline','content-view','data-view="board"','primary'));}
function contentList(){const items=all('content');return items.length?table(['Content','Business / client','Channel','Planned date','Status',''],items.map(c=>`<tr><td><strong>${esc(c.title)}</strong><span class="muted">${esc(c.format)}</span></td><td>${esc(bname(c.business_id))}<span class="muted">${esc(cname(c.client_id))}</span></td><td>${esc(c.channel)}</td><td>${shortDate(c.date)}</td><td>${badge(c.status)}</td><td>${editbtn('content',c.id,'Open')}</td></tr>`).join('')):empty('Your content starts here','Add an idea or a draft for any business or client.',addbtn('content','New content'));}
function contentCalendar(){const start=new Date(today()+'T12:00:00');start.setDate(1);start.setMonth(start.getMonth()+monthOffset);const label=start.toLocaleDateString('en-GB',{month:'long',year:'numeric'});const year=start.getFullYear(),month=start.getMonth();const first=new Date(year,month,1,12), offset=first.getDay();const count=new Date(year,month+1,0).getDate();const size=Math.ceil((count+offset)/7)*7;return `<div class="toolbar"><div class="week-navigation">${btn('Previous','month','data-offset="-1"','secondary compact')}<span class="month-label">${label}</span>${btn('Next','month','data-offset="1"','secondary compact')}</div>${btn('This month','month-reset','','secondary compact')}</div><div class="info">Dates show planned publishing. “Scheduled” means planned in GROW; no post is sent to a platform.</div><div class="card calendar-wrap"><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="calendar-heading">${d}</div>`).join('')}${Array.from({length:size},(_,i)=>{const d=new Date(year,month,i-offset+1,12);const ds=d.toISOString().slice(0,10),outside=d.getMonth()!==month;const items=all('content').filter(c=>c.date===ds&&c.status!=='Rejected');return `<div class="calendar-cell ${outside?'outside':''} ${ds===today()?'today':''}"><span class="day-number">${d.getDate()}</span>${items.map(c=>`<button class="calendar-event" style="border-color:${color(c.business_id)}" data-action="edit" data-entity="content" data-id="${esc(c.id)}">${esc(c.title)}</button>`).join('')}</div>`;}).join('')}</div></div>`;}
function salesPage(){const leads=all('leads');const stages=['Lead','Qualified','Contacted','Meeting','Proposal','Negotiation','Won','Lost'];return heading('Sales & relationships','Research, follow-ups and deal progress. Outreach stays under your control.',addbtn('leads','Add lead'))+`<div class="stats">${stat('Open pipeline',money(total(leads.filter(l=>!['Won','Lost'].includes(l.stage)),'value')),'Estimated · not revenue','sales',true)}${stat('Open leads',leads.filter(l=>!['Won','Lost'].includes(l.stage)).length,'Across active stages','clients')}${stat('Follow-ups due',leads.filter(l=>l.next_date&&l.next_date<=today()&&!['Won','Lost'].includes(l.stage)).length,'Today and overdue','clock')}${stat('Won deals',leads.filter(l=>l.stage==='Won').length,'Won value is not ledger income','check')}</div>${leads.length?table(['Company / lead','Business','Stage','Est. value','Next follow-up',''],leads.map(l=>`<tr><td><strong>${esc(l.name)}</strong><span class="muted">${esc(l.contact||l.email)}</span></td><td>${esc(bname(l.business_id))}</td><td>${badge(l.stage)}</td><td>${money(l.value)}</td><td>${shortDate(l.next_date)}${due(l.next_date)&&!['Won','Lost'].includes(l.stage)?` ${badge('Overdue')}`:''}</td><td>${editbtn('leads',l.id,'Open lead')}</td></tr>`).join('')):empty('Start a useful pipeline','Add a verified company, the next action and an estimated opportunity value.',addbtn('leads','Add lead'))}<div class="card section-gap"><div class="card-body"><h3>Pipeline stages</h3><p class="notice">${stages.join(' · ')}</p><p class="notice">No messages are sent by GROW. Use lead notes to prepare and review outreach.</p></div></div>`;}
function financePage(){const ts=ledger();const invoices=all('invoices');return heading('Finance & ledger','BDT income, expenses and client payments, separated by business.',`${addbtn('transactions','Add transaction')}${addbtn('invoices','New invoice')}`)+`<div class="stats">${stat('Monthly income',money(income(ts)),'Recorded cash received','finance',true)}${stat('Monthly expenses',money(expenses(ts)),'Recorded payments made','finance')}${stat('Net cash flow',money(income(ts)-expenses(ts)),'Income minus expenses','reports')}${stat('Receivables',money(total(invoices.map(i=>({amount:balance(i)})))),'All unpaid invoice balances','clock')}</div><div class="toolbar"><div class="tabs">${[['ledger','Ledger'],['invoices','Invoices'],['business','By business']].map(([v,l])=>`<button class="${financeView===v?'selected':''}" data-action="finance-view" data-view="${v}">${l}</button>`).join('')}</div>${btn('Export ledger CSV','export-ledger','','secondary compact')}</div>${financeView==='ledger'?ledgerTable():financeView==='invoices'?invoiceTable():businessFinance()}<p class="notice">This is a cash ledger, not a full accounting system. Invoices and subscriptions do not count as income or expenses until a payment is recorded. All amounts are in BDT.</p>`;}
function ledgerTable(){const items=all('transactions').sort((a,b)=>b.date.localeCompare(a.date));return items.length?table(['Transaction','Business / client','Category','Date','Amount',''],items.map(t=>`<tr><td><strong>${esc(t.title)}</strong><span class="muted">${esc(t.kind)}</span></td><td>${esc(bname(t.business_id))}<span class="muted">${esc(cname(t.client_id))}</span></td><td>${esc(t.category)}</td><td>${shortDate(t.date)}</td><td class="amount ${t.kind==='Expense'?'negative':''}">${t.kind==='Income'?'+':'−'}${money(t.amount)}</td><td>${t.invoice_id?'<span class="muted small">Invoice payment</span>':editbtn('transactions',t.id)}</td></tr>`).join('')):empty('Your ledger is ready','Record money received or spent. Invoice payments are added automatically when you record a payment.',addbtn('transactions','Add transaction'));}
function invoiceStatus(i){return balance(i)===0?'Paid':due(i.due)?'Overdue':i.paid>0?'Partial':'Unpaid';}
function invoiceTable(){const items=all('invoices');return items.length?table(['Invoice','Business / client','Amount / balance','Due','Status',''],items.map(i=>`<tr><td><strong>${esc(i.title)}</strong></td><td>${esc(bname(i.business_id))}<span class="muted">${esc(cname(i.client_id))}</span></td><td>${money(i.amount)}<span class="muted">${money(balance(i))} remaining</span></td><td>${shortDate(i.due)}</td><td>${badge(invoiceStatus(i))}</td><td><div class="page-actions">${balance(i)>0?btn('Record payment','payment',`data-id="${esc(i.id)}"`,'primary compact'):''}${editbtn('invoices',i.id)}</div></td></tr>`).join('')):empty('No invoices yet','Create a client invoice, then record received payments against it.',addbtn('invoices','New invoice'));}
function businessFinance(){return table(['Business','Income · month','Expenses · month','Net cash flow','Outstanding'],all('businesses').map(b=>{const ts=store.transactions.filter(t=>t.business_id===b.id&&inMonth(t.date)),inc=income(ts),exp=expenses(ts);return `<tr><td><div class="business-cell">${brandIcon(b.id)}<strong>${esc(b.name)}</strong></div></td><td>${money(inc)}</td><td>${money(exp)}</td><td class="amount ${inc-exp<0?'negative':''}">${money(inc-exp)}</td><td>${money(total(store.invoices.filter(i=>i.business_id===b.id).map(i=>({amount:balance(i)}))))}</td></tr>`;}).join(''));}
function resourcesPage(){const items=all('resources').filter(r=>!resourceType||r.type===resourceType);const recurring=all('resources').filter(r=>r.cycle==='Monthly'||r.cycle==='Annual');const monthly=Math.round(recurring.reduce((n,r)=>n+r.cost/(r.cycle==='Annual'?12:1),0));return heading('Resources & subscriptions','Know what you have, who owns it and when it renews.',addbtn('resources','Add resource'))+`<div class="stats">${stat('Resources',all('resources').length,'People, tools and creative assets','resources')}${stat('Recurring estimate',money(monthly),'Monthly equivalent · not ledger expense','finance',true)}${stat('Renewing soon',all('resources').filter(r=>r.renewal&&r.renewal>=today()&&r.renewal<=addDays(today(),7)).length,'Within the next 7 days','clock')}${stat('Shared resources',store.resources.filter(r=>!r.business_id).length,'Available across businesses','businesses')}</div><div class="toolbar"><div class="filters"><label class="small muted" for="resource-type">Resource type</label><select id="resource-type"><option value="">All types</option>${['Subscription','Domain','Hosting','Team','Asset','SOP','Software'].map(t=>`<option ${resourceType===t?'selected':''}>${t}</option>`).join('')}</select></div></div>${items.length?table(['Resource','Business','Type / owner','Cost','Renewal',''],items.map(r=>`<tr><td><strong>${esc(r.name)}</strong>${safeLink(r.url,'Open resource')}</td><td>${esc(bname(r.business_id))}</td><td>${badge(r.type)}<span class="muted">${esc(r.owner)}</span></td><td>${money(r.cost)}<span class="muted">${esc(r.cycle)}</span></td><td>${shortDate(r.renewal)}</td><td>${editbtn('resources',r.id)}</td></tr>`).join('')):empty('No resources in this view','Track a team member, subscription, domain, asset location or operating procedure.',addbtn('resources','Add resource'))}`;}
function automationsPage(){const items=all('recipes');return heading('Automation control','Prepare repeatable workflows before connecting your services.',addbtn('recipes','New workflow'))+`<div class="info">${icon('info')}Local planning mode. These workflows are saved recipes; no background jobs, publishing or external AI calls are running.</div><div class="three-column">${items.map(r=>`<article class="card recipe">${badge(r.enabled?'Included in plan':'Draft workflow')}<h3>${esc(r.title)}</h3><p class="muted small">${esc(bname(r.business_id))}</p><dl class="key-value section-gap"><div><dt>Trigger</dt><dd>${esc(r.trigger)}</dd></div></dl><pre>${esc(r.steps)}</pre><p class="notice"><strong>Output:</strong> ${esc(r.output)}</p><div class="actions section-gap">${editbtn('recipes',r.id,'Configure')}${btn('Export brief','export-recipe',`data-id="${esc(r.id)}"`,'secondary compact')}</div></article>`).join('')}${!items.length?empty('Design your first workflow','Describe the trigger, steps and expected output.',addbtn('recipes','New workflow')):''}</div><section class="section-gap">${card('Connections',`<div class="row-list">${[['Task manager',store.settings.task_manager_url?'URL saved · import snapshots manually':'Not connected'],['Publishing system','Not connected'],['AI service','Not connected'],['Website feeds','Not connected']].map(([n,s])=>`<div class="list-row"><div class="grow"><strong>${n}</strong><p>${s}</p></div>${badge('Manual setup')}</div>`).join('')}</div>`)}</section>`;}
function reportText(){const ts=ledger();return `GROW Weekly Review — ${today()}\nWorkspace: ${scope?bname(scope):'All businesses'}\n\nFINANCE (current month, BDT)\nIncome: ${money(income(ts))}\nExpenses: ${money(expenses(ts))}\nNet recorded cash flow: ${money(income(ts)-expenses(ts))}\nReceivables: ${money(total(openInvoices().map(i=>({amount:balance(i)}))))}\n\nCONTENT\nIn review: ${reviewItems().length}\nApproved: ${all('content').filter(c=>c.status==='Approved').length}\nPlanned in GROW: ${all('content').filter(c=>c.status==='Scheduled').length}\nMarked published: ${all('content').filter(c=>c.status==='Published').length}\n\nATTENTION\n${attentionItems().map(a=>'- '+a.title+': '+a.text).join('\n')||'No recorded exceptions.'}\n\nTASKS\nImported open statuses: ${all('tasks').filter(t=>t.status!=='Done').length}\nTask sync: manual snapshots only\n\nNEXT WEEK\n1. Protect Artbit deep work.\n2. Review content on Sunday and Thursday.\n3. Follow up qualified leads.\n4. Record income and expenses.\n\n${sampleCount()?'NOTE: Sample records are present. Figures may include sample amounts.':''}`;}
function reportsPage(){const ts=ledger(),inc=income(ts),exp=expenses(ts);const byBusiness=all('businesses').map(b=>{const t=store.transactions.filter(t=>t.business_id===b.id&&inMonth(t.date));return {name:b.name,net:income(t)-expenses(t)};});const max=Math.max(...byBusiness.map(x=>Math.abs(x.net)),1);return heading('Review & reports','A weekly decision view from the records you keep.',`${btn('Export weekly brief','export-review')}${addbtn('reviews','New weekly review')}`)+`<div class="stats">${stat('Net cash flow',money(inc-exp),'Current month · recorded cash only','reports',true)}${stat('Cash margin',inc?Math.round((inc-exp)/inc*100)+'%':'—','Net cash flow / recorded income','finance')}${stat('Approvals waiting',reviewItems().length,'Batch review on Sunday / Thursday','check')}${stat('Open delivery',all('projects').filter(p=>p.status!=='Done').length,'Projects not marked done','projects')}</div><div class="two-column">${card('Net cash flow by business',`<div class="card-body">${byBusiness.map(b=>`<div class="chart-row"><span>${esc(b.name)}</span><div class="bar-track"><div class="bar ${b.net<0?'loss':''}" style="width:${Math.abs(b.net)/max*100}%"></div></div><strong>${money(b.net)}</strong></div>`).join('')}<p class="notice">Bars show the magnitude of recorded net cash flow. Orange indicates a negative amount.</p></div>`)}${card('This week’s decisions',attentionRows(6))}</div><section class="section-gap">${card('Weekly review journal',all('reviews').length?`<div class="row-list">${all('reviews').slice().reverse().map(r=>`<div class="list-row"><div class="grow"><strong>${esc(r.title)}</strong><p>${shortDate(r.date)} · ${esc(r.next_week).slice(0,120)}</p></div>${editbtn('reviews',r.id,'Open review')}</div>`).join('')}</div>`:empty('Give next week a clear direction','Capture wins, blockers, decisions and the next week’s priorities.',addbtn('reviews','Start weekly review')))}</section>`;}
function localBrief(query='today'){const q=query.toLowerCase(),ts=ledger();let sections=[];if(/money|finance|invoice|cash|revenue/.test(q))sections.push(`FINANCE\n${money(income(ts))} received this month.\n${money(expenses(ts))} spent this month.\n${money(total(openInvoices().map(i=>({amount:balance(i)}))))} remains outstanding.\n${openInvoices().filter(i=>due(i.due)).length} invoices are overdue.`);else if(/content|approval|marketing|post/.test(q))sections.push(`CONTENT\n${reviewItems().length} items need review.\n${all('content').filter(c=>c.status==='Approved').length} are approved.\nReview days: ${store.settings.review_days}.\n\n${reviewItems().map(c=>'- '+c.title+' ('+bname(c.business_id)+')').join('\n')||'No content awaiting review.'}`);else if(/task/.test(q))sections.push(`TASKS\n${all('tasks').filter(t=>t.status!=='Done').length} imported task statuses are open.\nThese are snapshots, not live sync.\n${all('tasks').filter(t=>t.status==='Blocked').length} imported tasks are blocked.`);else sections.push(`TODAY’S FOCUS\nArtbit Studio + ${weekTheme()}.\n\nNEXT DECISIONS\n${attentionItems().slice(0,5).map((a,i)=>(i+1)+'. '+a.title+' — '+a.text).join('\n')||'No recorded exceptions. Keep your planned focus block.'}\n\nAPPROVALS\n${reviewItems().length} content items await review.\n\nFINANCE\nNet recorded cash flow this month: ${money(income(ts)-expenses(ts))}.`);return sections.join('\n\n')+'\n\nLocal brief based on saved records. Live AI is not connected.'+(sampleCount()?'\nSample records are included.':'');}
function aiPage(){return heading('GROW intelligence','A local decision brief, with exportable context for your AI tools.',badge('Live AI not connected'))+`<div class="two-column">${card('Your local brief',`<div class="card-body"><p class="muted small">Choose a brief for today, content, finance or imported tasks.</p><form id="brief-form" class="question-input"><input name="question" aria-label="Brief topic" placeholder="What should I focus on today?" maxlength="500"><button class="btn primary">Show brief</button></form><div class="quick-prompts">${['Today’s priorities','Content approvals','Finance and invoices','Task overview'].map(q=>btn(q,'brief',`data-query="${q}"`,'secondary compact')).join('')}</div><div id="brief-output" class="brief">${esc(localBrief())}</div></div>`)}${card('Prepare an AI content brief',`<div class="card-body"><p class="muted small">Build a prompt using your business profile. Copy it to your preferred AI tool; no request is sent from GROW.</p><form id="prompt-form" class="section-gap"><div class="form-row"><label for="prompt-business">Business</label><select name="business_id" id="prompt-business">${store.businesses.map(b=>`<option value="${esc(b.id)}" ${scope===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="form-row"><label for="prompt-topic">Topic or source brief</label><textarea name="topic" id="prompt-topic" placeholder="Describe the idea, source article or client brief…" required maxlength="20000"></textarea></div><div class="form-row"><label for="prompt-goal">Output</label><select name="output" id="prompt-goal"><option>Weekly content pack</option><option>Video script and repurposing plan</option><option>Marketing plan</option><option>Lead research and outreach draft</option></select></div><button class="btn primary">Build prompt</button></form></div>`)}</div>`;}
function settingsPage(){return heading('Workspace settings','Your data, task tool and recovery options.')+`<div class="settings-grid">${card('Workspace preferences',`<form id="settings-form" class="card-body"><div class="form-row"><label for="owner">Your name</label><input id="owner" name="owner" value="${esc(store.settings.owner||'Jubayer')}" required maxlength="100"></div><div class="form-row"><label for="task-manager-url">Existing task manager URL</label><input id="task-manager-url" name="task_manager_url" type="url" value="${esc(store.settings.task_manager_url)}" placeholder="http://localhost:3000"><small>GROW links to your tool and reads imported statuses. API sync requires your tool’s integration details.</small></div><div class="form-row"><label for="review-days">Content review days</label><input id="review-days" name="review_days" value="${esc(store.settings.review_days||'Sunday and Thursday')}" required></div><div class="form-row"><label>Ledger currency</label><input value="BDT · Bangladeshi taka" readonly><small>Single currency prevents mixed-currency totals. Convert external costs to BDT before recording.</small></div><button class="btn primary">Save preferences</button></form>`)}<div class="stack">${card('Backup & recovery',`<div class="card-body"><p class="muted">Export a complete JSON backup of your records. Keep a copy outside the app folder.</p><div class="page-actions section-gap"><a class="btn primary" href="/api/backup">${icon('down')} Export backup</a>${btn('Restore backup','restore')}</div><p class="notice">Restore replaces current records after confirmation. ${cloudMode?'Your records are stored in Cloudflare SQLite.':'The local database lives in data/grow.sqlite3.'}</p></div>`)}${card('Sample workspace',`<div class="card-body"><p class="muted">${sampleCount()} sample records are present. Your eight business workspaces are kept when you remove samples.</p><div class="section-gap">${btn('Remove sample records','clear-samples','','danger')}</div><p class="notice">New records you create are kept. Sample client links are cleared if their sample client is removed.</p></div>`)}${card('Connection status',`<div class="card-body"><dl class="key-value"><div><dt>Storage</dt><dd>${cloudMode?'Cloudflare SQLite':'Local SQLite database'} · active</dd></div><div><dt>Task manager</dt><dd>${store.settings.task_manager_url?'URL saved · manual snapshot import':'Not connected'}</dd></div><div><dt>AI, publishing and website feeds</dt><dd>Not connected</dd></div></dl><p class="notice">${cloudMode?'This edition saves records securely in Cloudflare. AI and publishing services are not connected.':'This edition runs on your computer and does not send records to external services.'}</p></div>`)}</div></div>`;}

// The same form and save path is used throughout the app.
const field=(key,label,type='text',required=false,options=[])=>({key,label,type,required,options});
const B=field('business_id','Business','business',true), C=field('client_id','Client','client');
const configs={
 businesses:{title:'Business',fields:[field('name','Business name','text',true),field('kind','Business type'),field('focus','Positioning / focus'),field('goal','Current goal','textarea'),field('channels','Channels'),field('target','Target audience','textarea'),field('pillars','Content pillars','textarea'),field('color','Workspace color','color')]},
 clients:{title:'Client',fields:[field('name','Client name','text',true),B,field('contact','Contact person'),field('email','Email','email'),field('fee','Monthly fee · BDT','money'),field('status','Status','select',true,['Active','Onboarding','Paused']),field('notes','Notes','textarea')]},
 projects:{title:'Project',fields:[field('title','Project title','text',true),B,C,field('due','Due date','date'),field('status','Status','select',true,['Planned','In progress','Review','Done']),field('notes','Delivery notes','textarea')]},
 content:{title:'Content',fields:[field('title','Title','text',true),B,C,field('channel','Channel','select',true,['Facebook','Instagram','LinkedIn','YouTube','YouTube Shorts','X','TikTok','Website']),field('format','Format','select',true,['Post','Carousel','Reel','Article','Video','Script']),field('status','Status','content-status',true),field('date','Planned publish date','date'),field('copy','Copy / script / source brief','textarea'),field('notes','Review notes / source links','textarea')]},
 leads:{title:'Lead',fields:[field('name','Company / lead','text',true),B,field('contact','Contact person'),field('email','Email','email'),field('stage','Stage','select',true,['Lead','Qualified','Contacted','Meeting','Proposal','Negotiation','Won','Lost']),field('value','Estimated value · BDT','money'),field('next_date','Next follow-up','date'),field('notes','Research / next action','textarea')]},
 transactions:{title:'Transaction',fields:[field('title','Description','text',true),B,C,field('kind','Type','select',true,['Income','Expense']),field('amount','Amount · BDT','money',true),field('date','Date','date',true),field('category','Category'),field('notes','Notes','textarea')]},
 invoices:{title:'Invoice',fields:[field('title','Invoice title / reference','text',true),B,C,field('amount','Invoice amount · BDT','money',true),field('date','Invoice date','date',true),field('due','Due date','date',true),field('notes','Notes','textarea')]},
 resources:{title:'Resource',fields:[field('name','Resource name','text',true),field('business_id','Business','business'),field('type','Type','select',true,['Subscription','Domain','Hosting','Team','Asset','SOP','Software']),field('owner','Owner / responsible person'),field('cost','Cost · BDT','money'),field('cycle','Billing cycle','select',true,['Monthly','Annual','One-time','None']),field('renewal','Renewal / review date','date'),field('url','Resource URL / file location','url'),field('notes','Notes / SOP instructions','textarea')]},
 plans:{title:'Marketing plan',fields:[field('title','Plan title','text',true),B,field('objective','Objective','textarea'),field('audience','Target audience','textarea'),field('channels','Channels'),field('pillars','Content pillars','textarea'),field('cadence','Posting cadence'),field('kpi','Success metric'),field('date','Start date','date'),field('notes','Plan / actions','textarea')]},
 reviews:{title:'Weekly review',fields:[field('title','Review title','text',true),field('date','Review date','date',true),field('wins','Wins / what worked','textarea'),field('blockers','Blockers / what did not work','textarea'),field('decisions','Decisions made','textarea'),field('next_week','Next week’s priorities','textarea')]},
 recipes:{title:'Workflow',fields:[field('title','Workflow name','text',true),field('business_id','Business','business'),field('trigger','Trigger','textarea',true),field('steps','Steps','textarea',true),field('output','Expected output','textarea'),field('enabled','Include in workflow plan (does not run jobs)','checkbox')]}
};
const transitions={'Idea':['Draft','Rejected'],'Draft':['In review','Rejected'],'In review':['Approved','Changes requested','Rejected'],'Changes requested':['Draft','In review','Rejected'],'Approved':['Scheduled','Draft','Rejected'],'Scheduled':['Published','Approved'],'Published':[],'Rejected':['Draft']};
function option(value,label,selected){return `<option value="${esc(value)}" ${String(selected)===String(value)?'selected':''}>${esc(label)}</option>`;}
function formField(f,record,entity){let v=record[f.key];if(v===undefined){v=f.type==='business'?(scope||(entity==='clients'?'artbit':store.businesses[0]?.id)||''):f.type==='money'?0:f.type==='date'&&['date'].includes(f.key)?today():f.type==='select'?f.options[0]:f.type==='color'?'#628779':f.type==='content-status'?'Draft':'';}
let input;const req=f.required?'required':'';const attrs=`id="field-${f.key}" name="${f.key}" ${req}`;
if(f.type==='textarea')input=`<textarea ${attrs} maxlength="20000" ${f.key==='copy'?'style="min-height:170px"':''}>${esc(v)}</textarea>`;
else if(['select','business','client','content-status'].includes(f.type)){let opts=f.options.map(x=>[x,x]);if(f.type==='business')opts=(f.required?[]:[['','Shared / all businesses']]).concat(store.businesses.map(b=>[b.id,b.name]));if(f.type==='client')opts=[['','No client']].concat(store.clients.filter(c=>c.business_id===(record.business_id||scope||(entity==='clients'?'artbit':store.businesses[0]?.id))).map(c=>[c.id,c.name]));if(f.type==='content-status')opts=record.id?[record.status,...(transitions[record.status]||[])].map(x=>[x,x]):[['Idea','Idea'],['Draft','Draft']];input=`<select ${attrs}>${opts.map(([value,label])=>option(value,label,v)).join('')}</select>`;}
else if(f.type==='checkbox')input=`<label class="switch-label"><input class="checkbox" type="checkbox" ${attrs} ${v?'checked':''}>Include in planning</label>`;
else input=`<input ${attrs} type="${f.type==='money'?'number':f.type}" ${f.type==='money'?'min="0" step="0.01" max="1000000000000"':''} value="${esc(f.type==='money'?Number(v||0)/100:v)}" ${['text','email','url'].includes(f.type)?'maxlength="1000"':''}>`;
return `<div class="form-row ${f.type==='textarea'||f.type==='checkbox'?'wide':''}"><label for="field-${f.key}">${esc(f.label)}${f.required?' *':''}</label>${input}</div>`;}
function openDialog(content){const dialog=$('#editor');dialog.innerHTML=content;if(!dialog.open)dialog.showModal();}
const dialogHead=(title,subtitle='')=>`<div class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button data-action="close" type="button" aria-label="Close dialog">${icon('close')}</button></div>`;
function openEditor(entity,id='',defaults={}){const config=configs[entity];if(!config)return;const record=id?found(entity,id):defaults;if(!record)return toast('Record no longer exists.',true);openDialog(`${dialogHead((id?'Edit ':'New ')+config.title,id&&record.demo?'Sample record':entity==='content'?'Draft → Review → Approve → Plan → Confirm published':'Saved to your workspace')}<form id="record-form" data-entity="${entity}" data-id="${esc(id)}"><div class="dialog-body"><div id="form-error"></div>${entity==='invoices'&&id?`<div class="info">Paid ${money(record.paid)} · Balance ${money(balance(record))}</div>`:''}${entity==='content'&&id&&['Approved','Scheduled','Published'].includes(record.status)?'<div class="info">Approved content is protected. Save it as Draft before changing the title, copy or channel. Published records are kept as history.</div>':''}<div class="form-grid">${config.fields.map(f=>formField(f,record,entity)).join('')}</div></div><div class="dialog-actions">${id?btn('Delete record','delete-record',`type="button" data-entity="${entity}" data-id="${esc(id)}"`,'danger'):''}<button class="btn secondary" data-action="close" type="button">Cancel</button><button type="submit" class="btn primary">Save ${config.title.toLowerCase()}</button></div></form>`);}
function formError(error){const el=$('#form-error');if(el){el.innerHTML=`<div class="form-error" role="alert">${esc(error.message||error)}</div>`;el.scrollIntoView({block:'nearest'});}else toast(error.message||error,true);}
async function saveRecord(form){const entity=form.dataset.entity,id=form.dataset.id;const raw=new FormData(form),data={};for(const f of configs[entity].fields){const val=raw.get(f.key);data[f.key]=f.type==='money'?Math.round(Number(val||0)*100):f.type==='checkbox'?val!==null:String(val??'');}const button=form.querySelector('button[type="submit"]');button.disabled=true;try{await api(entity+(id?'/'+id:''),id?'PATCH':'POST',data);await refresh();$('#editor').close();render();toast('Saved to your workspace.');}catch(e){formError(e);}finally{button.disabled=false;}}
function confirmDialog(title,text,action,label='Confirm'){openDialog(`${dialogHead(title)}<div class="dialog-body"><p>${esc(text)}</p><div id="form-error"></div></div><div class="dialog-actions">${btn('Cancel','close')}${btn(label,action,'','danger')}</div>`);}
async function contentStatus(id,status){const c=found('content',id);if(!c||!transitions[c.status]?.includes(status))return toast('This status change is not allowed.',true);if(status==='Scheduled'||status==='Published'){return openDialog(`${dialogHead(status==='Scheduled'?'Plan this content':'Confirm publication',c.title)}<form id="content-transition" data-id="${esc(id)}" data-status="${status}"><div class="dialog-body"><div class="info">${status==='Scheduled'?'This records your publishing plan in GROW. It does not publish or schedule a post on an external platform.':'Confirm only after you have published this asset on the external platform.'}</div><div id="form-error"></div><div class="form-row"><label for="publish-date">${status==='Published'?'Actual publish date':'Planned publish date'}</label><input id="publish-date" name="date" type="date" value="${esc(c.date||today())}" required></div></div><div class="dialog-actions"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn primary">${status==='Published'?'Confirm published':'Save plan'}</button></div></form>`);}
if(status==='Changes requested'||status==='Rejected'){return openDialog(`${dialogHead(status==='Rejected'?'Reject this content':'Request changes',c.title)}<form id="content-transition" data-id="${esc(id)}" data-status="${status}"><div class="dialog-body"><div id="form-error"></div><div class="form-row"><label for="review-notes">Review notes</label><textarea id="review-notes" name="notes" required placeholder="Explain what should change…">${esc(c.notes)}</textarea></div></div><div class="dialog-actions"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn primary">Save review</button></div></form>`);}
await api('content/'+id,'PATCH',{status});await refresh();render();toast(status==='Approved'?'Approved. Ready for your publishing plan.':'Content moved to '+status+'.');}
function openPayment(id){const inv=found('invoices',id);openDialog(`${dialogHead('Record invoice payment',inv.title)}<form id="payment-form" data-id="${esc(id)}"><div class="dialog-body"><div class="info">${money(balance(inv))} outstanding. This payment adds income to the ledger and reduces the invoice balance together.</div><div id="form-error"></div><div class="form-row"><label for="payment-amount">Payment received · BDT</label><input id="payment-amount" name="amount" type="number" min="0.01" step="0.01" max="${balance(inv)/100}" value="${balance(inv)/100}" required></div><div class="form-row"><label for="payment-date">Date received</label><input id="payment-date" name="date" type="date" value="${today()}" required></div></div><div class="dialog-actions"><button type="button" data-action="close" class="btn secondary">Cancel</button><button class="btn primary">Record payment</button></div></form>`);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function uploadJSON(action){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>4*1024*1024)return toast('Choose a JSON file smaller than 4 MB.',true);try{const data=JSON.parse(await file.text());if(action==='restore'){window.pendingRestore=data;confirmDialog('Restore this backup?','This replaces the current workspace. Export a backup first if you want to keep your current records.','confirm-restore','Restore workspace');}else{const result=await api('import-tasks','POST',data);await refresh();render();toast(result.record.count+' task statuses imported.');}}catch(e){toast(e.message||'Invalid JSON file.',true);}};input.click();}
function searchDialog(){openDialog(`${dialogHead('Search your workspace')}<div class="dialog-body"><div class="form-row"><input id="global-search" type="search" aria-label="Search all records" placeholder="Business, client, content, project…" autofocus></div><div id="search-results" class="search-results"><p class="muted small">Type to search names and titles across your saved records.</p></div></div>`);}
function showSearch(q){const results=[];for(const entity of Object.keys(entityPage)){for(const r of store[entity]){const title=r.title||r.name;if(title&&title.toLowerCase().includes(q.toLowerCase()))results.push({entity,r,title});}}$('#search-results').innerHTML=q?results.slice(0,30).map(({entity,r,title})=>`<button class="search-result" data-action="search-result" data-entity="${entity}" data-id="${esc(r.id)}">${icon(entityPage[entity])}<div><strong>${esc(title)}</strong><small>${esc(entity)} · ${esc(r.business_id?bname(r.business_id):'Workspace')}</small></div></button>`).join('')||'<p class="muted small">No matching records.</p>':'<p class="muted small">Type to search names and titles.</p>';}
function promptFrom(form){const data=new FormData(form),b=business(data.get('business_id'));return `You are helping prepare ${data.get('output')} for ${b.name}.\n\nBRAND CONTEXT\nFocus: ${b.focus}\nAudience: ${b.target}\nChannels: ${b.channels}\nPillars: ${b.pillars}\nCurrent goal: ${b.goal}\n\nTOPIC / SOURCE BRIEF\n${data.get('topic')}\n\nREQUIREMENTS\n- Use the supplied brand context and a practical marketing objective.\n- Keep each platform’s version distinct and concise.\n- Identify claims that need sources or expert review; do not invent facts, results, or testimonials.\n- Include headline, supporting copy, caption, visual direction and image/video prompt where relevant.\n- Propose a Sunday/Thursday batch-review schedule.\n- Human review is required before any publishing or outreach.\n- Do not change existing brand logos, names or character designs.\n- Label assumptions and missing information clearly.\n\nReturn a clear, editable draft. Do not publish or send anything.`;}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;event.preventDefault();if(el.disabled)return;try{
 if(a==='navigate'){if($('#editor').open)$('#editor').close();go(el.dataset.page);}
 else if(a==='logout'){await api('logout','POST',{});location.replace('/login');}
 else if(a==='menu')$('#sidebar').classList.toggle('open');
 else if(a==='close')$('#editor').close();
 else if(a==='edit')openEditor(el.dataset.entity,el.dataset.id);
 else if(a==='workspace'){scope=el.dataset.id;go('businesses');}
 else if(a==='clear-scope'){scope='';render();}
 else if(a==='content-view'){contentView=el.dataset.view;render();}
 else if(a==='finance-view'){financeView=el.dataset.view;render();}
 else if(a==='content-approvals'){contentView='approvals';go('content');}
 else if(a==='review-content'){contentView='approvals';go('content');}
 else if(a==='content-status'){el.disabled=true;await contentStatus(el.dataset.id,el.dataset.status);}
 else if(a==='month'){monthOffset+=Number(el.dataset.offset);render();}
 else if(a==='month-reset'){monthOffset=0;render();}
 else if(a==='payment')openPayment(el.dataset.id);
 else if(a==='search')searchDialog();
 else if(a==='search-result'){const entity=el.dataset.entity,id=el.dataset.id;$('#editor').close();go(entityPage[entity]);if(configs[entity])openEditor(entity,id);}
 else if(a==='client-delivery'){const c=found('clients',el.dataset.id);scope=c.business_id;const contents=store.content.filter(r=>r.client_id===c.id),projects=store.projects.filter(r=>r.client_id===c.id);openDialog(`${dialogHead(c.name,'Client delivery overview')}<div class="dialog-body"><h3>Projects</h3>${projects.length?projects.map(p=>`<div class="list-row"><div class="grow"><strong>${esc(p.title)}</strong><p>${shortDate(p.due)}</p></div>${badge(p.status)}${editbtn('projects',p.id)}</div>`).join(''):'<p class="notice">No projects linked to this client.</p>'}<h3 class="section-gap">Content</h3>${contents.length?contents.map(c=>`<div class="list-row"><div class="grow"><strong>${esc(c.title)}</strong><p>${esc(c.channel)}</p></div>${badge(c.status)}${editbtn('content',c.id,'Open')}</div>`).join(''):'<p class="notice">No content linked to this client.</p>'}</div><div class="dialog-actions">${btn('Add client project','new-client-project',`data-id="${esc(c.id)}"`)}${btn('Add client content','new-client-content',`data-id="${esc(c.id)}"`,'primary')}</div>`);}
 else if(a==='new-client-project'||a==='new-client-content'){const c=found('clients',el.dataset.id);openEditor(a==='new-client-project'?'projects':'content','',{business_id:c.business_id,client_id:c.id});}
 else if(a==='import-tasks')uploadJSON('tasks');
 else if(a==='restore')uploadJSON('restore');
 else if(a==='confirm-restore'){el.disabled=true;await api('restore','POST',window.pendingRestore);delete window.pendingRestore;await refresh();scope='';$('#editor').close();render();toast('Workspace restored.');}
 else if(a==='clear-samples')confirmDialog('Remove sample records?','Your eight businesses and any new records you created are kept. Sample content, clients, invoices and other examples will be removed. Export a backup first if needed.','confirm-clear','Remove samples');
 else if(a==='confirm-clear'){el.disabled=true;await api('clear-samples','POST',{});await refresh();$('#editor').close();render();toast('Sample records removed.');}
 else if(a==='delete-record'){window.pendingDelete={entity:el.dataset.entity,id:el.dataset.id};confirmDialog('Delete this record?','This removes the record from your workspace. Linked records must be removed or reassigned first.','confirm-delete','Delete record');}
 else if(a==='confirm-delete'){el.disabled=true;await api(window.pendingDelete.entity+'/'+window.pendingDelete.id,'DELETE',{});delete window.pendingDelete;await refresh();if(scope&&!business(scope))scope='';$('#editor').close();render();toast('Record deleted.');}
 else if(a==='export-review')download('grow-weekly-review-'+today()+'.txt',reportText());
 else if(a==='export-recipe'){const r=found('recipes',el.dataset.id);download('grow-workflow-'+r.id+'.txt',`${r.title}\nBusiness: ${bname(r.business_id)}\nTrigger: ${r.trigger}\n\n${r.steps}\n\nOutput: ${r.output}\n\nPlanning mode. No connected execution.`);}
 else if(a==='export-ledger'){const cell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['Date','Business','Client','Type','Description','Category','Amount (BDT)'],...all('transactions').map(t=>[t.date,bname(t.business_id),cname(t.client_id),t.kind,t.title,t.category,(t.amount/100).toFixed(2)])];download('grow-ledger-'+today()+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
 else if(a==='task-example')download('grow-task-import-example.json',JSON.stringify({tasks:[{external_id:'your-task-123',title:'Review campaign',business_id:scope||'artbit',status:'Open',priority:'High',due:today(),url:store.settings.task_manager_url||''}]},null,2),'application/json');
 else if(a==='brief')$('#brief-output').textContent=localBrief(el.dataset.query);
 else if(a==='copy-prompt'){const text=$('#generated-prompt').value;try{await navigator.clipboard.writeText(text);toast('Prompt copied.');}catch{$('#generated-prompt').select();toast('Select and copy the prompt with Ctrl+C.');}}
 }catch(e){if($('#editor').open)formError(e);else toast(e.message,true);}finally{if(el.isConnected)el.disabled=false;}
});
document.addEventListener('change',e=>{if(e.target.id==='scope'){scope=e.target.value;render();}if(e.target.id==='resource-type'){resourceType=e.target.value;render();}if(e.target.id==='field-business_id'){const select=$('#field-client_id');if(select)select.innerHTML=option('','No client','')+store.clients.filter(c=>c.business_id===e.target.value).map(c=>option(c.id,c.name,'')).join('');}});
document.addEventListener('input',e=>{if(e.target.id==='global-search')showSearch(e.target.value.trim());});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;try{
 if(form.id==='record-form')await saveRecord(form);
 else if(form.id==='settings-form'){await api('settings','PATCH',Object.fromEntries(new FormData(form)));await refresh();render();toast('Preferences saved.');}
 else if(form.id==='payment-form'){const data=new FormData(form),button=form.querySelector('button:not([type="button"])');button.disabled=true;try{await api('invoices/'+form.dataset.id+'/payment','POST',{amount:Math.round(Number(data.get('amount'))*100),date:data.get('date')});await refresh();$('#editor').close();render();toast('Payment recorded; ledger and invoice updated.');}finally{button.disabled=false;}}
 else if(form.id==='content-transition'){const data=Object.fromEntries(new FormData(form));data.status=form.dataset.status;await api('content/'+form.dataset.id,'PATCH',data);await refresh();$('#editor').close();render();toast('Content updated.');}
 else if(form.id==='brief-form')$('#brief-output').textContent=localBrief(new FormData(form).get('question'));
 else if(form.id==='prompt-form'){const text=promptFrom(form);openDialog(`${dialogHead('Your AI content brief','Copy this prompt into your preferred AI tool.')}<div class="dialog-body"><textarea id="generated-prompt" class="prompt-output" aria-label="Generated AI prompt" readonly>${esc(text)}</textarea></div><div class="dialog-actions">${btn('Close','close')}${btn('Copy prompt','copy-prompt','','primary')}</div>`);}
 }catch(error){if($('#editor').open)formError(error);else toast(error.message,true);}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==page){page=NAV.some(n=>n[0]===next)?next:'home';render();}});

async function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});try{
 await context.registerTool({name:'grow_read_workspace',title:'Read GROW workspace',description:'Read a concise overview of saved saved records. Does not change state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');return {businesses:store.businesses.map(b=>({id:b.id,name:b.name})),contentReviewCount:store.content.filter(c=>c.status==='In review').length,sampleRecords:sampleCount(),liveConnections:false};}},{signal:controller.signal});
 await context.registerTool({name:'grow_navigate_workspace',title:'Open GROW view',description:'Navigate to a business or module without changing saved records.',inputSchema:{type:'object',properties:{page:{type:'string',enum:NAV.map(n=>n[0])},business_id:{type:'string'}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['page','business_id'].includes(k))||!NAV.some(n=>n[0]===input.page))throw new Error('Choose a valid page.');if(input.business_id!==undefined&&!business(input.business_id))throw new Error('Business not found.');scope=input.business_id||'';go(input.page);return {page,scope};}},{signal:controller.signal});
 }catch(e){console.warn('Optional browser tools are unavailable.');}}
async function boot(){try{await refresh();page=NAV.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'home';render();await registerTools();}catch(e){$('#app').innerHTML=`<div class="boot"><div><h2>GROW could not open</h2><p class="muted">${esc(e.message)} ${cloudMode?'Refresh this page to try again.':'Keep the local server running, then refresh this page.'}</p></div></div>`;}}
boot();
